from __future__ import annotations

from collections.abc import MutableSequence
from typing import Protocol, TypeVar

__all__ = ["bubble_sort"]


class _Comparable(Protocol):
    def __gt__(self, other: object) -> bool:
        ...


_Item = TypeVar("_Item", bound=_Comparable)


def bubble_sort(items: MutableSequence[_Item]) -> None:
    """Sort items in ascending order in place using bubble sort."""
    for pass_end in range(len(items) - 1, 0, -1):
        swapped = False

        for index in range(pass_end):
            if items[index] > items[index + 1]:
                items[index], items[index + 1] = items[index + 1], items[index]
                swapped = True

        if not swapped:
            break
